SELECT table_name, column_name, data_type FROM information_schema.columns
WHERE table_schema='warehouse' AND table_name IN ('shipping_notice_lines','stock_adjustments')
ORDER BY table_name, ordinal_position;

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY table_schema, table_name;

SELECT kind, count(*) AS n, min(complaint_ts) AS first_ts, max(complaint_ts) AS last_ts
FROM payments.customer_complaints
GROUP BY kind ORDER BY n DESC;

SELECT count(*) rows, count(DISTINCT bill_id) bills, sum(amount_inr) FILTER (WHERE till_status='approved') approved_sum,
       count(*) FILTER (WHERE till_status='approved') approved_rows
FROM payments.pos_payments WHERE ts >= TIMESTAMP '2026-06-01' AND ts < TIMESTAMP '2026-07-01';

SELECT substring(bill_id from 10 for 2) AS till, count(DISTINCT bill_id) bills, count(*) rows, sum(amount_inr) FILTER (WHERE till_status='approved') amt
FROM payments.pos_payments WHERE ts >= TIMESTAMP '2026-06-01' AND ts < TIMESTAMP '2026-07-01'
GROUP BY 1 ORDER BY 1;
